template <> struct Fields<::sc_old_equipment::sc::MusicSynth> { static auto of(::sc_old_equipment::sc::MusicSynth& x) { return std::tie(x.peak, x.rate_, x.programme_, x.want_, x.gain_, x.target_, x.fade_, x.sample_, x.step_, x.samples_per_step_, x.until_step_, x.rng_, x.kick_, x.snare_, x.hat_, x.bass_, x.lead_, x.pad_, x.lp_, x.bass_lp_, x.echo_, x.echo_at_); } static auto of(const ::sc_old_equipment::sc::MusicSynth& x) { return std::tie(x.peak, x.rate_, x.programme_, x.want_, x.gain_, x.target_, x.fade_, x.sample_, x.step_, x.samples_per_step_, x.until_step_, x.rng_, x.kick_, x.snare_, x.hat_, x.bass_, x.lead_, x.pad_, x.lp_, x.bass_lp_, x.echo_, x.echo_at_); } };
